def somme_recursive(n):
    if n == 0:
        return 0
    return n + somme_recursive(n - 1)

def factorielle(n):
    if n == 0:
        return 1
    return n * factorielle(n - 1)

def fibonacci(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

def contient(liste, cible):
    if liste == []:
        return False
    if liste[0] == cible:
        return True
    return contient(liste[1:], cible)

def nb_deplacements(n):
    if n == 0:
        return 0
    return 2 * nb_deplacements(n - 1) + 1

def temps_total(n, secondes=5):
    return nb_deplacements(n) * secondes

